<template><div class="page profile-page"><Header/><main><ProfileSidebar/><section class="profile-content"><div><h1>Shipping Address</h1><div v-if="status==='loading'" class="state">Loading addresses…</div><div v-else-if="status==='unauthorized'" class="state error">Please log in with a customer account to manage shipping addresses.</div><div v-else-if="status==='error'" class="state error">{{errorMessage}}<button class="retry" @click="loadAddresses">Retry</button></div><div v-else-if="!addresses.length" class="state">No shipping addresses yet.</div><article v-for="a in addresses" :key="String(a.addressId)" class="address-card"><div class="card-head"><h3>{{fullName(a)||'Unnamed recipient'}}</h3><span v-if="isDefault(a)" class="default-label">Default</span></div><p v-if="phone(a)" class="phone">{{phone(a)}}</p><p class="address-lines">{{addressLine(a)||'Address details unavailable'}}</p><footer><button v-if="!isDefault(a)" class="link-button" @click="setDefault(a)" :disabled="defaultingId!==null">{{defaultingId===String(a.addressId)?'Setting…':'Set as default'}}</button><span v-else class="default-text">Default address</span><div><button class="link-button" @click="beginEdit(a)">Edit</button><button class="link-button danger" @click="requestDelete(a)" :disabled="deletingAddressId===String(a.addressId)">{{deletingAddressId===String(a.addressId)?'Deleting…':'Delete'}}</button></div></footer></article></div><aside class="add-panel"><h1>{{mode==='edit'?'Edit Address':'Add Address'}}</h1><div v-if="formMessage" class="form-message" :class="{error:formError}">{{formMessage}}</div><div class="form-grid"><label>First name<input v-model.trim="form.firstName" :disabled="saving"></label><label>Last name<input v-model.trim="form.lastName" :disabled="saving"></label><label>Phone code<input v-model.trim="form.phoneCode" :disabled="saving"></label><label>Phone number<input v-model.trim="form.phoneNumber" :disabled="saving"></label><label class="full">Address line 1<input v-model.trim="form.line1" :disabled="saving"></label><label class="full">Address line 2<input v-model.trim="form.line2" :disabled="saving"></label><label>City<input v-model.trim="form.city" :disabled="saving"></label><label>Region / State<input v-model.trim="form.region" :disabled="saving"></label><label>Postal code<input v-model.trim="form.postalCode" :disabled="saving"></label><label>Country code<input v-model.trim="form.countryCode" :disabled="saving"></label></div><label class="check"><input type="checkbox" v-model="form.isDefault" :disabled="saving"> Set as default shipping address</label><label class="check"><input type="checkbox" v-model="form.isConstructionSite" :disabled="saving"> This is a construction site</label><div class="actions"><button @click="mode==='edit'?cancelEdit():resetForm()" :disabled="saving">Cancel</button><button class="save" @click="saveAddress" :disabled="saving||mode==='create'&&addresses.length>=10">{{saving?'Saving…':mode==='edit'?'Save changes':'Save address'}}</button></div></aside></section></main><Footer/><div v-if="pendingDelete" class="mask"><div class="confirm"><h2>Delete Address</h2><p>Are you sure you want to delete this shipping address?</p><div class="confirm-actions"><button @click="pendingDelete=null">Cancel</button><button class="danger-button" @click="confirmDelete">Delete</button></div></div></div></div></template>
<script setup lang="ts">
import {onMounted,ref} from 'vue';import Header from '@/components/Header.vue';import Footer from '@/components/Footer.vue';import ProfileSidebar from '@/components/ProfileSidebar.vue';import {AddressApiError,createAddress,updateAddress,deleteAddress,setDefaultAddress,getAddressList,type AddressBody,type AddressRecord} from '@/api/addresses';import {getCustomerAuthState} from '@/utils/customerAuth'
type FormState={firstName:string;lastName:string;phoneCode:string;phoneNumber:string;countryCode:string;region:string;city:string;line1:string;line2:string;postalCode:string;isDefault:boolean;isConstructionSite:boolean};const emptyForm=():FormState=>({firstName:'',lastName:'',phoneCode:'',phoneNumber:'',countryCode:'',region:'',city:'',line1:'',line2:'',postalCode:'',isDefault:false,isConstructionSite:false});const form=ref<FormState>(emptyForm());const addresses=ref<AddressRecord[]>([]);const status=ref<'loading'|'success'|'empty'|'error'|'unauthorized'>('loading');const errorMessage=ref('Unable to load addresses. Please try again.');const saving=ref(false);const formMessage=ref('');const formError=ref(false);const mode=ref<'create'|'edit'>('create');const editingAddressId=ref<string|null>(null);const originalIsDefault=ref(false);const pendingDelete=ref<AddressRecord|null>(null);const deletingAddressId=ref<string|null>(null);const defaultingId=ref<string|null>(null)
function isDefault(a:AddressRecord){return a.isDefault===1||a.isDefault==='1'||a.isDefault===true};async function loadAddresses(){if(!getCustomerAuthState().isAuthenticated){status.value='unauthorized';addresses.value=[];return false}status.value='loading';try{addresses.value=await getAddressList();status.value=addresses.value.length?'success':'empty';return true}catch(e){if(e instanceof AddressApiError&&(e.status===401||e.status===403))status.value='unauthorized';else{status.value='error';errorMessage.value=e instanceof Error?e.message:'Unable to load addresses. Please try again.'};return false}}
async function setDefault(a:AddressRecord){if(isDefault(a)||defaultingId.value!==null)return;const auth=getCustomerAuthState();if(!auth.isAuthenticated){status.value='unauthorized';return}const id=String(a.addressId);defaultingId.value=id;const previous=addresses.value.slice();try{await setDefaultAddress(id);const refreshed=await loadAddresses();if(refreshed)formMessage.value='Default address updated successfully.';else{addresses.value=previous;formError.value=true;formMessage.value='Default address updated, but the list could not be refreshed. Please retry.'}}catch(e){formError.value=true;formMessage.value=e instanceof Error?e.message:'Unable to set default address.'}finally{defaultingId.value=null}}
function beginEdit(a:AddressRecord){mode.value='edit';editingAddressId.value=String(a.addressId);originalIsDefault.value=isDefault(a);form.value={firstName:a.firstName||'',lastName:a.lastName||'',phoneCode:a.phoneCode||'',phoneNumber:a.phoneNumber||'',countryCode:a.countryCode||'',region:a.region||'',city:a.city||'',line1:a.line1||'',line2:a.line2||'',postalCode:a.postalCode||'',isDefault:originalIsDefault.value,isConstructionSite:Number(a.notConstructionSite)===0};formMessage.value='';formError.value=false};function resetForm(clear=true){mode.value='create';editingAddressId.value=null;originalIsDefault.value=false;form.value=emptyForm();if(clear){formMessage.value='';formError.value=false}};function cancelEdit(){resetForm()};function requestDelete(a:AddressRecord){if(!deletingAddressId.value)pendingDelete.value=a};async function confirmDelete(){const a=pendingDelete.value;if(!a)return;const id=String(a.addressId);const prev=addresses.value.slice();pendingDelete.value=null;deletingAddressId.value=id;try{await deleteAddress(id);const ok=await loadAddresses();if(!ok)addresses.value=prev;if(ok&&editingAddressId.value===id)resetForm(false);formMessage.value=ok?'Address deleted successfully.':'Address deleted successfully, but the list could not be refreshed. Please retry.';formError.value=!ok}catch(e){formError.value=true;formMessage.value=e instanceof Error?e.message:'Unable to delete address.'}finally{deletingAddressId.value=null}}
function validate(){for(const [k,n] of [['firstName','First name'],['lastName','Last name'],['phoneCode','Phone code'],['phoneNumber','Phone number'],['countryCode','Country code'],['region','Region / State'],['city','City'],['line1','Address line 1'],['postalCode','Postal code']] as [keyof FormState,string][])if(!String(form.value[k]).trim())return n+' is required.';if(!/^\+?[0-9 ()-]{1,8}$/.test(form.value.phoneCode))return'Phone code is invalid.';if(!/^[0-9 ()-]{5,20}$/.test(form.value.phoneNumber))return'Phone number is invalid.';if(!/^[A-Za-z0-9 -]{3,12}$/.test(form.value.postalCode))return'Postal code is invalid.';return''};function bodyForSave():AddressBody|Partial<AddressBody>{const b:any={firstName:form.value.firstName,lastName:form.value.lastName,phoneCode:form.value.phoneCode,phoneNumber:form.value.phoneNumber,countryCode:form.value.countryCode,region:form.value.region,city:form.value.city,line1:form.value.line1,line2:form.value.line2,postalCode:form.value.postalCode,notConstructionSite:form.value.isConstructionSite?'0':'1'};if(mode.value==='create'||form.value.isDefault!==originalIsDefault.value)b.isDefault=form.value.isDefault?'1':'0';return b}
async function saveAddress(){formMessage.value='';formError.value=false;const auth=getCustomerAuthState();if(!auth.isAuthenticated){status.value='unauthorized';formError.value=true;formMessage.value='Please log in with a customer account before saving.';return}if(mode.value==='create'&&addresses.value.length>=10){formError.value=true;formMessage.value='You have reached the 10-address limit.';return}const v=validate();if(v){formError.value=true;formMessage.value=v;return}if(saving.value)return;if(mode.value==='edit'&&!editingAddressId.value){formError.value=true;formMessage.value='Address ID is missing.';return}saving.value=true;const edit=mode.value==='edit';try{if(edit)await updateAddress(editingAddressId.value as string,bodyForSave());else await createAddress(bodyForSave() as AddressBody);const ok=await loadAddresses();formMessage.value=ok?(edit?'Address updated successfully.':'Address added successfully.'):(edit?'Address updated, but the list could not be refreshed. Please retry.':'Address added successfully, but the list could not be refreshed. Please retry.');if(ok)resetForm(false)}catch(e){formError.value=true;formMessage.value=e instanceof Error?e.message:'Unable to save address.'}finally{saving.value=false}}
function fullName(a:AddressRecord){return[a.firstName,a.lastName].filter(Boolean).join(' ')};function phone(a:AddressRecord){return[a.phoneCode,a.phoneNumber].filter(Boolean).join(' ')};function addressLine(a:AddressRecord){return[a.line1,a.line2,a.city,a.region,a.countryCode,a.postalCode].filter(Boolean).join(', ')};function unsupported(f:string){window.alert(f+' is unavailable until the backend API is provided.')};onMounted(loadAddresses)
</script>
<style scoped>.page{background:#f4f4f5;min-height:100vh;color:#333;font:13px Arial,sans-serif}.page main{display:flex;width:100%;background:#fff;min-height:680px}.profile-content{flex:1;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(300px,.85fr);gap:16px;padding:18px;background:#f4f4f5}.profile-content h1{font-size:18px;font-weight:600;margin:0 0 12px}.address-card,.add-panel{background:#fff;border:1px solid #dfe3e8;border-radius:7px;padding:15px;margin-bottom:10px;min-width:0}.card-head{display:flex;align-items:center;gap:9px}.card-head h3{font-size:15px;font-weight:600;margin:0}.default-label{font-size:11px;color:#0879b5;background:#eff8fc;border-radius:4px;padding:3px 7px}.address-card p{margin:7px 0}.phone,.address-lines{font-size:13px;line-height:1.5;overflow-wrap:anywhere}.address-card footer{border-top:1px solid #edf0f2;padding-top:10px;margin-top:12px;display:flex;justify-content:space-between;gap:8px}.link-button{border:0;background:none;padding:0;color:#0879b5;font-size:12px;cursor:pointer}.link-button+.link-button{margin-left:14px}.danger,.error{color:#a63805}.state{padding:28px 14px;text-align:center;color:#8a929a;background:#fff;border:1px dashed #dfe3e8;border-radius:7px}.retry{display:block;margin:12px auto;padding:6px 12px}.form-message{font-size:12px;margin:0 0 10px;color:#28734b}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form-grid label{font-size:12px;color:#555}.full{grid-column:1/-1}.form-grid input{display:block;width:100%;box-sizing:border-box;height:35px;margin-top:5px;padding:0 9px;border:1px solid #dfe3e8;border-radius:4px;font-size:13px}.check{display:block;margin-top:10px;font-size:12px}.actions,.confirm-actions{display:flex;gap:8px;margin-top:15px}.actions button,.confirm-actions button{height:34px;flex:1;border:1px solid #b7bec6;background:#fff;border-radius:4px;font-size:13px}.save,.danger-button{background:#333!important;color:#fff;border-color:#333!important}.mask{position:fixed;inset:0;background:#0005;display:flex;align-items:center;justify-content:center}.confirm{background:#fff;padding:20px;border-radius:7px;width:min(420px,calc(100vw - 32px))}.confirm h2{font-size:16px}.danger-button{background:#a63805!important;border-color:#a63805!important}@media(max-width:800px){.page main{display:block}.profile-content{grid-template-columns:1fr;padding:12px}.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}
</style>
